#!/bin/bash
# Release assets are generated by tools/build-bootstrap-release.py.
set -euo pipefail
umask 077

version='@CCHOUSE_VERSION@'
source_sha='@CCHOUSE_SHA256@'
python_asset='cpython-3.12.16%2B20261124-aarch64-apple-darwin-install_only_stripped.tar.gz'
python_url="https://github.com/astral-sh/python-build-standalone/releases/download/20261124/$python_asset"
python_sha='9d6d9d0d85feda3f9cb4eb3e048f0fed21ed280feda087927eaa4fbc7124826f'
mihomo_version='v1.19.19'
mihomo_url="https://github.com/MetaCubeX/mihomo/releases/download/${mihomo_version}/mihomo-darwin-arm64-${mihomo_version}.gz"
mihomo_sha='29fdde431e69e17f4e8e7cda2046402c4cba254a26ad66ce17e37ad946490dc0'
tart_url='https://github.com/openai/tart/releases/download/2.42.0/tart.tar.gz'
tart_sha='a95dda214b5f676298430d665a8174992e6b300dd20c653385b60481ae819ddf'

stage=''
lock=''
bootstrap_to_remove=''
tag="${CCHOUSE_TAG:-cc01}"
image_mirror="${CCHOUSE_IMAGE_MIRROR:-}"
npm_mirror="${CCHOUSE_NPM_MIRROR:-}"
share_dir="${CCHOUSE_SHARE:-}"
share_read_only=0
link_file=""
link_clipboard=0
reconfigure=0
bootstrap_mirror="${CCHOUSE_BOOTSTRAP_MIRROR:-}"
curl_bin="${CCHOUSE_CURL_BIN:-curl}"
fetch_max_attempts="${CCHOUSE_BOOTSTRAP_RETRIES:-6}"
fetch_base_backoff="${CCHOUSE_BOOTSTRAP_BACKOFF:-2}"

cleanup() {
  if [ -n "$stage" ]; then rm -rf -- "$stage"; fi
  if [ -n "$lock" ]; then rmdir -- "$lock"; fi
  if [ -n "$bootstrap_to_remove" ]; then rm -f -- "$bootstrap_to_remove"; fi
}
trap cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' TERM

while [ "$#" -gt 0 ]; do
  case "$1" in
    --cleanup-bootstrap)
      case "${0##*/}" in
        cchouse-bootstrap.*) bootstrap_to_remove="$0" ;;
      esac
      shift
      ;;
    --tag)
      if [ "$#" -lt 2 ]; then echo '--tag 需要一个实例名。' >&2; exit 2; fi
      tag="$2"
      shift 2
      ;;
    --image-mirror)
      if [ "$#" -lt 2 ]; then echo '--image-mirror 需要一个 URL。' >&2; exit 2; fi
      image_mirror="$2"
      shift 2
      ;;
    --npm-mirror)
      if [ "$#" -lt 2 ]; then echo '--npm-mirror 需要一个 URL。' >&2; exit 2; fi
      npm_mirror="$2"
      shift 2
      ;;
    --share)
      if [ "$#" -lt 2 ]; then echo '--share 需要一个本地文件夹路径。' >&2; exit 2; fi
      share_dir="$2"
      shift 2
      ;;
    --share-read-only)
      share_read_only=1
      shift
      ;;
    --link-file)
      if [ "$#" -lt 2 ]; then echo '--link-file 需要一个文件路径。' >&2; exit 2; fi
      link_file="$2"
      shift 2
      ;;
    --link-clipboard)
      link_clipboard=1
      shift
      ;;
    --reconfigure)
      reconfigure=1
      shift
      ;;
    *) echo '用法：bootstrap-macos.sh [--tag <实例名>] [--image-mirror <URL>] [--npm-mirror <URL>] [--share <路径>] [--share-read-only] [--link-clipboard] [--link-file <路径>] [--reconfigure]' >&2; exit 2 ;;
  esac
done
if [[ ! "$tag" =~ ^[a-z][a-z0-9_-]{1,15}$ ]]; then
  echo '实例名须以小写字母开头，共 2–16 位，可用小写字母、数字、下划线和短横线。' >&2
  exit 2
fi
if [ "$(uname -s)" != Darwin ] || [ "$(sysctl -n hw.optional.arm64 2>/dev/null || true)" != 1 ]; then
  echo '此安装入口需要 Apple Silicon Mac。' >&2
  exit 1
fi
macos_version="$(sw_vers -productVersion)"
if [ "${macos_version%%.*}" -lt 13 ]; then
  echo '此安装入口需要 macOS 13.0（Ventura）或更新版本。' >&2
  exit 1
fi
if [[ ! "$source_sha" =~ ^[0-9a-f]{64}$ ]]; then
  echo '请使用 GitHub Release 上已固定版本和 SHA-256 的引导脚本。' >&2
  exit 1
fi

shell_quote() {
  printf "'%s'" "$(printf '%s' "$1" | sed "s/'/'\\\\''/g")"
}

build_home_cmd() {
  local self_sha=''
  if [ -f "$0" ]; then
    self_sha="$(shasum -a 256 "$0" | awk '{print $1}')"
  fi
  local cmd="f=\$(mktemp -t cchouse-bootstrap) && curl -fsSLo \"\$f\" https://github.com/nana-fox/cchouse/releases/download/${version}/bootstrap-macos.sh && printf '%s  %s\\n' '${self_sha}' \"\$f\" | shasum -a 256 -c - && /bin/bash \"\$f\" --cleanup-bootstrap"
  if [ "$tag" != 'cc01' ]; then
    cmd="${cmd} --tag $(shell_quote "$tag")"
  fi
  if [ -n "$image_mirror" ]; then
    cmd="${cmd} --image-mirror $(shell_quote "$image_mirror")"
  fi
  if [ -n "$npm_mirror" ]; then
    cmd="${cmd} --npm-mirror $(shell_quote "$npm_mirror")"
  fi
  if [ -n "$share_dir" ]; then
    cmd="${cmd} --share $(shell_quote "$share_dir")"
  fi
  if [ "$share_read_only" = 1 ]; then
    cmd="${cmd} --share-read-only"
  fi
  printf '%s\n' "$cmd"
}

if [ -n "$link_file" ]; then
  case "$link_file" in
    /*) ;;
    ~/*) link_file="$HOME/${link_file#\~/}" ;;
    *) link_file="$(pwd)/$link_file" ;;
  esac
fi

instance_env="$HOME/Library/Application Support/cchouse/$tag/instance.env"
home_cmd="$(build_home_cmd)"
export CCHOUSE_HOME_CMD="$home_cmd"
if [ \( ! -f "$instance_env" -o "$reconfigure" = 1 \) ] && [ -z "$link_file" ] && [ "$link_clipboard" = 0 ] && [ ! -t 0 ]; then
  echo ''
  echo '需要你本人输入节点链接：请在你自己的终端窗口运行下面这条命令（AI 无法也不应替你输入）'
  echo ''
  echo "$home_cmd"
  exit 20
fi

root="$HOME/Library/Application Support/cchouse/bootstrap"
python_home="$root/tools/python-3.12.16-20261124"
mihomo_home="$root/tools/mihomo-$mihomo_version"
mihomo_bin="$mihomo_home/mihomo"
tart_home="$root/tools/tart-2.42.0"
code="$root/packages/$version-${source_sha:0:12}"
echo "cchouse $version 将校验并准备私有 Python 和源码，写入 ${root}。"
if command -v tart >/dev/null && tart --version >/dev/null 2>&1; then
  echo '将复用本机 Tart。'
  needs_tart=0
  export CCHOUSE_TART_BIN="$(command -v tart)"
elif [ -x "$tart_home/Contents/MacOS/tart" ] && "$tart_home/Contents/MacOS/tart" --version >/dev/null 2>&1; then
  echo '将复用已准备的私有 Tart。'
  needs_tart=0
  export CCHOUSE_TART_BIN="$tart_home/Contents/MacOS/tart"
  export PATH="$tart_home/Contents/MacOS:$PATH"
else
  echo '将从官方 Release 校验并准备私有 Tart。'
  needs_tart=1
fi
if [ -f "$instance_env" ] && [ "$reconfigure" = 0 ]; then
  echo '检测到已有节点配置，随后启动 cchouse up 继续安装或重建。'
elif [ "$link_clipboard" = 1 ]; then
  echo '随后启动 cchouse up，从本机剪贴板读取节点配置（不回显，保存后自动清空）。'
elif [ -n "$link_file" ]; then
  echo '随后启动 cchouse up，从指定的链接文件读取节点配置。'
else
  echo '随后启动 cchouse up，按提示输入节点链接。'
fi

mkdir -p "$root/downloads" "$root/tools" "$root/packages"
if ! mkdir "$root/.prepare"; then
  echo '另一个 cchouse 引导正在准备文件。若上次被强制结束，确认没有引导在运行后删除 bootstrap/.prepare 再试。' >&2
  exit 1
fi
lock="$root/.prepare"
stage="$(mktemp -d "$root/.install.XXXXXXXX")"

verified() {
  [ -f "$1" ] && printf '%s  %s\n' "$2" "$1" | shasum -a 256 -c - >/dev/null
}

fetch() {
  local label="$1" url="$2" sha="$3" dest="$4"
  local part="${dest}.part"
  local attempt=1
  local use_http11=0
  local wait_secs="$fetch_base_backoff"
  local effective_url="$url"
  local rc=0
  local curl_args=()

  if [ -n "$bootstrap_mirror" ]; then
    effective_url="${bootstrap_mirror%/}/${url##*/}"
  fi

  if verified "$dest" "$sha"; then
    echo "[引导依赖] ${label} 已缓存且校验通过，跳过。"
    return 0
  fi

  while [ "$attempt" -le "$fetch_max_attempts" ]; do
    local had_part=0
    if [ -f "$part" ]; then
      local have_bytes
      have_bytes="$(wc -c < "$part" | tr -d ' ')"
      if [ "$have_bytes" -gt 0 ]; then
        had_part=1
      fi
      echo "[引导依赖] 下载 ${label}（第 ${attempt}/${fetch_max_attempts} 次，从 ${have_bytes} 字节处断点续传）..."
    else
      echo "[引导依赖] 下载 ${label}（第 ${attempt}/${fetch_max_attempts} 次）..."
    fi

    curl_args=(
      -fL -C -
      --proto '=https' --proto-redir '=https'
      --connect-timeout 20
      --speed-limit 10240 --speed-time 30
    )
    if [ "$use_http11" = 1 ]; then
      curl_args+=(--http1.1)
    fi

    rc=0
    "$curl_bin" "${curl_args[@]}" "$effective_url" -o "$part" || rc=$?

    if [ "$rc" -eq 0 ]; then
      if verified "$part" "$sha"; then
        mv -f -- "$part" "$dest"
        echo "[引导依赖] ${label} 下载并校验完成。"
        return 0
      fi
      rm -f -- "$part"
      if [ "$had_part" -eq 1 ] && [ "$attempt" -lt "$fetch_max_attempts" ]; then
        echo "[引导依赖] ${label} 续传结果 SHA-256 不匹配，已删除旧分片并从头重下..." >&2
      else
        echo "SHA-256 校验失败：[引导依赖] ${label}（${url##*/}），已删除损坏文件。" >&2
        exit 1
      fi
    else
      case "$rc" in
        18|56|92)
          if [ "$use_http11" = 0 ]; then
            echo "[引导依赖] ${label} 遇到连接/HTTP2 异常（curl 退出码 ${rc}），切换 --http1.1 并保留已下载分片继续续传..." >&2
            use_http11=1
          else
            echo "[引导依赖] ${label} 下载中断（curl 退出码 ${rc}），保留已下载分片继续续传..." >&2
          fi
          ;;
        33)
          echo "[引导依赖] ${label} 服务器拒绝断点续传（curl 33），清理分片重新下载..." >&2
          rm -f -- "$part"
          ;;
        *)
          echo "[引导依赖] ${label} 下载失败（curl 退出码 ${rc}），已下载分片保留在 ${part}..." >&2
          ;;
      esac
    fi

    if [ "$attempt" -lt "$fetch_max_attempts" ]; then
      echo "[引导依赖] ${wait_secs}s 后重试..." >&2
      sleep "$wait_secs"
      wait_secs=$((wait_secs * 2))
      if [ "$wait_secs" -gt 32 ]; then
        wait_secs=32
      fi
    fi
    attempt=$((attempt + 1))
  done

  echo "" >&2
  echo "✗ [引导依赖] ${label} 下载失败（已重试 ${fetch_max_attempts} 次）。" >&2
  echo "  已下载的分片已保留在：${part}" >&2
  echo "  下一步建议：" >&2
  echo "  1. 直接重新运行同一条首页命令，会自动从断点继续下载；" >&2
  echo "  2. 如当前开了代理导致 GitHub CDN 不稳，可尝试切换节点或临时取消 HTTPS_PROXY / ALL_PROXY 后重跑；" >&2
  echo "  3. 也可设置 CCHOUSE_BOOTSTRAP_MIRROR=<镜像目录URL> 后重跑（仍会严格校验 SHA-256）。" >&2
  exit 1
}

install_tar() {
  local artifact="$1" dest="$2" member="$3"
  if [ -d "$dest" ]; then return; fi
  mkdir "$stage/tar"
  tar -xzf "$artifact" -C "$stage/tar"
  mv -- "$stage/tar/$member" "$dest"
  rm -rf -- "$stage/tar"
}

source_zip="$root/downloads/cchouse-$version-$source_sha.zip"
fetch "cchouse 源码包" "https://github.com/nana-fox/cchouse/releases/download/$version/cchouse-$version.zip" "$source_sha" "$source_zip"
python_tar="$root/downloads/python-$python_sha.tar.gz"
fetch "私有 Python" "$python_url" "$python_sha" "$python_tar"
install_tar "$python_tar" "$python_home" python

if [ ! -x "$mihomo_bin" ]; then
  mihomo_gz="$root/downloads/mihomo-$mihomo_version-$mihomo_sha.gz"
  fetch "临时探测组件 mihomo $mihomo_version" "$mihomo_url" "$mihomo_sha" "$mihomo_gz"
  mkdir -p "$mihomo_home"
  gzip -dc "$mihomo_gz" >"$stage/mihomo"
  chmod 700 "$stage/mihomo"
  mv -f -- "$stage/mihomo" "$mihomo_bin"
fi
export CCHOUSE_MIHOMO_BIN="$mihomo_bin"

if [ ! -d "$code" ]; then
  mkdir "$stage/zip"
  /usr/bin/ditto -x -k "$source_zip" "$stage/zip"
  test -f "$stage/zip/cchouse/scripts/cchouse.py"
  mv -- "$stage/zip/cchouse" "$code"
fi
rmdir -- "$lock"
lock=''

export PATH="$python_home/bin:$PATH"
export PYTHONUTF8=1
cd "$code"
if [ "$("$python_home/bin/python3" -I scripts/cchouse.py --version)" != "cchouse $version" ]; then
  echo '源码包版本与引导脚本不一致。请使用对应版本的 Release 引导脚本。' >&2
  exit 1
fi

# 安装 ~/.local/bin/cchouse 命令入口
"$python_home/bin/python3" -I -c "import sys; sys.path.insert(0, 'scripts'); import launcher; launcher.install_cli_entry()" || true

# 若本机缺少 Tart 且尚未验证节点，先完成节点探测再下载私有 Tart（节点不行不白等）
pre_configured=0
if [ "$needs_tart" = 1 ] && [ ! -f "$instance_env" -o "$reconfigure" = 1 ]; then
  pre_args=(up --tag "$tag" --config-only --skip-preflight)
  if [ "$link_clipboard" = 1 ]; then
    pre_args+=(--link-clipboard)
  fi
  if [ -n "$link_file" ]; then
    pre_args+=(--link-file "$link_file")
  fi
  if [ "$reconfigure" = 1 ]; then
    pre_args+=(--reconfigure)
  fi
  "$python_home/bin/python3" -I scripts/cchouse.py "${pre_args[@]}"
  pre_configured=1
fi

if [ "$needs_tart" = 1 ]; then
  if ! mkdir "$root/.prepare"; then
    echo '另一个 cchouse 引导正在准备文件。若上次被强制结束，确认没有引导在运行后删除 bootstrap/.prepare 再试。' >&2
    exit 1
  fi
  lock="$root/.prepare"
  tart_tar="$root/downloads/tart-$tart_sha.tar.gz"
  fetch "私有 Tart" "$tart_url" "$tart_sha" "$tart_tar"
  install_tar "$tart_tar" "$tart_home" tart.app
  export CCHOUSE_TART_BIN="$tart_home/Contents/MacOS/tart"
  export PATH="$tart_home/Contents/MacOS:$PATH"
  "$CCHOUSE_TART_BIN" --version >/dev/null
  rmdir -- "$lock"
  lock=''
fi

up_args=(up --tag "$tag")
if [ -n "$image_mirror" ]; then
  up_args+=(--image-mirror "$image_mirror")
fi
if [ -n "$npm_mirror" ]; then
  up_args+=(--npm-mirror "$npm_mirror")
fi
if [ -n "$share_dir" ]; then
  up_args+=(--share "$share_dir")
fi
if [ "$share_read_only" = 1 ]; then
  up_args+=(--read-only)
fi
if [ "$pre_configured" = 0 ]; then
  if [ "$link_clipboard" = 1 ]; then
    up_args+=(--link-clipboard)
  fi
  if [ -n "$link_file" ]; then
    up_args+=(--link-file "$link_file")
  fi
  if [ "$reconfigure" = 1 ]; then
    up_args+=(--reconfigure)
  fi
fi

echo "正在启动 cchouse up。重跑同一条首页命令可续跑。工作目录：$code"
"$python_home/bin/python3" -I scripts/cchouse.py "${up_args[@]}"
